library IEEE;use IEEE_Std_Logic_1164.all;entity Prob_5_45_Seq_Detector_vhdl is	port (detect: out bit; bit_in, clk, reset_b: in bit);end Prob_5_45_Seq_Detector_vhdl;architecture Behavioral of Prob_5_45_Seq_Detector_vhdl is	constant S0: Std_Logic_vector (1 downto 0) := "00";  	constant S1: Std_Logic_vector (1 downto 0) := "01";	constant S2: Std_Logic_vector (1 downto 0) := "10";	constant S3: Std_Logic_vector (1 downto 0) := "11";	signal state, next_state: Std_Logic_vector (1 downto 0);begin	detect <= '1' when state = S3;	process  (clk, reset_b) begin 		if reset_b = '0' then state <= S0; 		elsif clk'event and clk = '1' then state <= next_state; end if;	end process;  	process (state, bit_in) begin    		next_state <= S0;    		case (state) is      		when S0 =>	if bit_in = '1' then next_state <= S1; else state <= S0; end if;      		when S1 =>	if bit_in = '1' then next_state <= S2; else next_state <= S0; end if;      		when S2 =>	if bit_in = '1' then next_state <= S3; else state <= S0; end if;      		when S3 =>	if bit_in = '1' then next_state <= S3; else next_state <= S0; end if;      		when others =>	next_state <= S0;    		end case;  	end process;end Behavioral;